/**
 * The base URL of a service, as the deploy test's runner resolved it: Compose publishes each
 * service on an ephemeral host port, so no test can name the port. A service the runner resolved
 * no URL for throws, naming it.
 */
export function serviceBaseUrl(serviceDir: string): string {
  const resolved = (JSON.parse(process.env.DEPLOY_TEST_SERVICE_URLS ?? '{}') as Record<string, string>)[serviceDir];
  if (!resolved) {
    throw new Error(`deploy_test_service_url_missing service=${serviceDir}`);
  }
  return resolved;
}

